<script setup lang="ts">
const props=defineProps<{settings:any,csrf:string}>(),emit=defineEmits(['saved'])
const form=ref<any>({...props.settings,start:new Date().toLocaleDateString('sv-SE'),weeks:1})
const names=['Lun','Mar','Mer','Gio','Ven','Sab','Dom']
const preview=ref<any>(null),kind=ref(''),message=ref(''),busy=ref(false)
const fmt=(v:any)=>v==null?'—':Number(v).toLocaleString('it-IT',{maximumFractionDigits:0})
let settingsSnapshot=JSON.stringify(props.settings)
// Calendar navigation can reload identical preferences while the athlete edits a draft.
watch(()=>props.settings,v=>{const snapshot=JSON.stringify(v);if(snapshot!==settingsSnapshot){settingsSnapshot=snapshot;form.value={...form.value,...v}}},{deep:true})
watch(form,()=>{preview.value=null},{deep:true})
async function request(target:string,confirm=false){
 busy.value=true;message.value=''
 try{
  const url=target==='block'?'/api/platform/training':'/api/platform/memory'
  const body=confirm?{kind:'training-settings',confirm:true,preview_token:preview.value.preview_token}:{...form.value,kind:'training-settings'}
  const r=await $fetch<any>(url,{method:'POST',headers:{'x-csrf-token':props.csrf},body})
  if(confirm){preview.value=null;message.value=target==='block'?'Blocco salvato nel calendario.':'Disponibilità e obiettivi salvati.';emit('saved')}
  else {preview.value=r;kind.value=target}
 }catch(e:any){message.value=e.data?.error||'Operazione non completata'}finally{busy.value=false}
}
</script>
<template><div class="panel space-y-4"><div><p class="eyebrow">IL TUO PROGRAMMA · MEMORIA PERSISTENTE</p><h2 class="text-xl font-semibold mt-2">Disponibilità, obiettivi e prossimo blocco</h2></div><p v-if="settings.confirmed===false" class="muted">{{settings.source}}</p><label class="block text-sm">Obiettivo attuale<textarea v-model="form.goal" class="w-full mt-2" rows="2" aria-label="Obiettivo attuale" placeholder="Gara, distanza o lavoro da concordare con il tuo allenatore"/></label><div class="flex flex-wrap gap-4"><label v-for="(name,i) in names" class="text-sm flex items-center gap-2"><input type="checkbox" :value="i" v-model="form.weekdays"/>{{name}}</label></div><div class="grid sm:grid-cols-3 gap-3"><label class="text-xs">Minuti disponibili a seduta<input v-model.number="form.max_minutes" type="number" min="20" max="240" class="block w-full mt-1" aria-label="Minuti disponibili"/></label><label class="text-xs">Gara obiettivo<input v-model="form.race_name" class="block w-full mt-1" aria-label="Gara obiettivo"/></label><label class="text-xs">Data gara<input v-model="form.race_date" type="date" class="block w-full mt-1" aria-label="Data gara"/></label><label class="text-xs">Distanza gara · m<input v-model.number="form.race_distance_m" type="number" min="0" max="50000" class="block w-full mt-1"/></label><label class="text-xs">Ambiente obiettivo<select v-model="form.environment" class="block w-full mt-1"><option value="pool">Piscina</option><option value="open_water">Acque libere</option></select></label></div><UButton @click="request('preferences')" :loading="busy" variant="outline">Anteprima preferenze</UButton><hr class="border-zinc-800"/><div class="flex flex-wrap gap-3 items-end"><label class="text-xs">Inizio del blocco<input v-model="form.start" type="date" class="block mt-1" aria-label="Inizio blocco"/></label><label class="text-xs">Durata<select v-model.number="form.weeks" class="block mt-1" aria-label="Settimane blocco"><option v-for="n in 4" :value="n">{{n}} settimane</option></select></label><UButton @click="request('block')" :loading="busy">Proponi blocco dal carico recente</UButton></div><p class="muted">La proposta locale mantiene il volume recente, rispetta giorni e durata dichiarati e non applica progressioni automatiche. È una base di piscina da rivedere con il coach; la specificità per una gara in mare va discussa.</p><div v-if="preview" class="rounded-xl border border-green-800 p-4 space-y-3"><h3 class="font-semibold text-green-400">{{kind==='block'?'Anteprima del blocco':'Anteprima delle preferenze'}}</h3><template v-if="kind==='block'"><p>{{preview.preview.sessions.length}} sedute · {{fmt(preview.preview.total_m)}} m totali · riferimento settimanale {{fmt(preview.preview.weekly_reference_m)}} m</p><p class="muted">{{preview.preview.n_history}} sedute dal {{preview.preview.history_start}} al {{preview.preview.history_end}}</p><div class="table-wrap"><table><thead><tr><th>Data</th><th>Allenamento</th><th>Volume</th><th>Serie</th></tr></thead><tbody><tr v-for="s in preview.preview.sessions"><td>{{s.date}}</td><td>{{s.title}}</td><td>{{fmt(s.total_m)}} m</td><td><p v-for="b in s.blocks">{{b.label}} · {{b.reps}} × {{b.distance_m}} m · {{b.zone}} · rec {{b.rest_s}}s</p></td></tr></tbody></table></div><p v-for="text in [...preview.preview.basis,...preview.preview.limits]" class="muted">{{text}}</p></template><template v-else><p>{{preview.preview.goal||'Obiettivo non dichiarato'}}</p><p class="muted">Giorni: {{preview.preview.weekdays.map((i:number)=>names[i]).join(', ')}} · {{preview.preview.max_minutes}} min/seduta</p><p class="muted">{{preview.preview.race_name||'Nessuna gara'}} · {{preview.preview.race_date||'data non dichiarata'}}</p></template><UButton @click="request(kind,true)" :loading="busy">{{kind==='block'?'Conferma e salva il blocco':'Conferma preferenze'}}</UButton></div><p role="status" class="text-sm text-amber-300">{{message}}</p></div></template>
